const timing = $input.first().json;

// План из Create Video Plan
const planNode = $items('Create Video Plan')[0].json;
const plan = JSON.parse(planNode.output[0].content[0].text);

const words = timing.words || [];

if (!words.length) {
  throw new Error('No word timestamps received');
}

// Нормализация текста для сопоставления сцен с Whisper.
// Mercedes-AMG -> ["mercedes", "amg"]
// V-8 -> ["v", "8"]
// 4.0-liter -> ["4", "0", "liter"]
function tokenize(text) {
  return (
    String(text)
      .toLowerCase()
      .match(/[a-z0-9]+(?:['’][a-z0-9]+)?/g) || []
  );
}

// Разворачиваем Whisper words в токены,
// сохраняя связь с исходным word index.
const flatWords = [];

words.forEach((word, wordIndex) => {
  const tokens = tokenize(word.word);

  for (const token of tokens) {
    flatWords.push({
      token,
      wordIndex,
    });
  }
});

// Ищем начало сцены в транскрипции.
// Сначала по первым 4 словам, затем по 3, затем по 2.
function findSceneStart(sceneTokens, fromIndex) {
  for (const probeLength of [4, 3, 2]) {
    if (sceneTokens.length < probeLength) continue;

    const probe = sceneTokens.slice(0, probeLength);

    for (
      let i = fromIndex;
      i <= flatWords.length - probeLength;
      i++
    ) {
      let match = true;

      for (let j = 0; j < probeLength; j++) {
        if (flatWords[i + j].token !== probe[j]) {
          match = false;
          break;
        }
      }

      if (match) {
        return i;
      }
    }
  }

  return -1;
}

const sceneTokenCounts = plan.scenes.map(scene =>
  tokenize(scene.text).length
);

const totalSceneTokens = sceneTokenCounts.reduce(
  (sum, count) => sum + count,
  0
);

const sceneStarts = [];

let searchFrom = 0;
let consumedSceneTokens = 0;

for (let i = 0; i < plan.scenes.length; i++) {
  const scene = plan.scenes[i];
  const sceneTokens = tokenize(scene.text);

  let flatIndex = findSceneStart(sceneTokens, searchFrom);

  // Fallback, если начало сцены не удалось точно найти.
  if (flatIndex === -1) {
    const ratio =
      totalSceneTokens > 0
        ? consumedSceneTokens / totalSceneTokens
        : 0;

    flatIndex = Math.round(
      ratio * Math.max(0, flatWords.length - 1)
    );
  }

  const wordIndex =
    flatWords[Math.min(flatIndex, flatWords.length - 1)]
      ?.wordIndex ?? 0;

  sceneStarts.push(words[wordIndex]?.start ?? 0);

  searchFrom = Math.min(
    flatWords.length,
    flatIndex + Math.max(
      1,
      Math.floor(sceneTokens.length * 0.6)
    )
  );

  consumedSceneTokens += sceneTokens.length;
}

// Первая сцена всегда начинается с начала видео.
if (sceneStarts.length) {
  sceneStarts[0] = 0;
}

const totalDuration =
  timing.duration ??
  words[words.length - 1]?.end ??
  0;

// --------------------------------------------------
// SCENES
// --------------------------------------------------

const scenes = plan.scenes.map((scene, index) => {
  const start = sceneStarts[index];

  const end =
    index < plan.scenes.length - 1
      ? sceneStarts[index + 1]
      : totalDuration;

  return {
    text: scene.text,
    image_url: scene.image_url,
    motion: scene.motion,
    start,
    end,
    duration: Math.max(0, end - start),
  };
});

// --------------------------------------------------
// SUBTITLES
// 3–5 слов.
// Subtitle никогда не пересекает границу сцены.
// --------------------------------------------------

const subtitles = [];

for (const scene of scenes) {
  const sceneWords = words.filter(word =>
    word.start >= scene.start &&
    word.start < scene.end
  );

  let chunks = [];
  let current = [];

  for (let i = 0; i < sceneWords.length; i++) {
    const word = sceneWords[i];
    const next = sceneWords[i + 1];

    current.push(word);

    const pause = next
      ? Math.max(0, next.start - word.end)
      : Infinity;

    const maxWordsReached = current.length >= 5;

    const naturalPause =
      current.length >= 3 &&
      pause >= 0.4;

    const isLastWord = !next;

    if (
      maxWordsReached ||
      naturalPause ||
      isLastWord
    ) {
      chunks.push(current);
      current = [];
    }
  }

  // Не оставляем в конце сцены отдельный subtitle
  // из 1–2 слов, если его можно объединить
  // с предыдущим блоком.
  if (
    chunks.length >= 2 &&
    chunks[chunks.length - 1].length < 3
  ) {
    const last = chunks.pop();

    chunks[chunks.length - 1].push(...last);
  }

  for (const chunk of chunks) {
    subtitles.push({
      start: chunk[0].start,
      end: chunk[chunk.length - 1].end,
      text: chunk
        .map(word => word.word)
        .join(' '),
    });
  }
}

// --------------------------------------------------
// OUTPUT
// --------------------------------------------------

return [
  {
    json: {
      title: plan.title,
      caption: plan.caption,
      script: plan.script,
      duration: totalDuration,
      scenes,
      subtitles,
    },
  },
];

