node <<'NODE'
const fs=require('fs'),path=require('path'),http=require('http'),https=require('https');
const {execFileSync}=require('child_process');

(async()=>{
const w=process.env.WORKDIR;
const d=JSON.parse(fs.readFileSync(path.join(w,'render-data.json'),'utf8'));
const voice=path.join(w,'voiceover.mp3');
const ass=path.join(w,'subtitles.ass');
const list=path.join(w,'concat.txt');
const joined=path.join(w,'joined.mp4');
const out=path.join(w,'video.mp4');
const fps=30;

const BASE_SIZE=64;
const ACTIVE_SCALE=112;
const MAX_GROUP_WORDS=4;
const MAX_GROUP_WIDTH=730;
const PAUSE_BREAK=0.38;
const VISIBLE_GAP=0.16;

function dl(url,dest,r=0){
 return new Promise((ok,bad)=>{
  const m=url.startsWith('https:')?https:http;
  m.get(url,res=>{
   if([301,302,303,307,308].includes(res.statusCode)&&res.headers.location&&r<5){
    const u=new URL(res.headers.location,url).toString();
    res.resume();
    return ok(dl(u,dest,r+1));
   }

   if(res.statusCode!==200){
    res.resume();
    return bad(new Error(`HTTP ${res.statusCode}: ${url}`));
   }

   const f=fs.createWriteStream(dest);

   res.pipe(f);

   f.on('finish',()=>f.close(ok));
   f.on('error',bad);

  }).on('error',bad);
 });
}

function ff(a){
 execFileSync(
  'ffmpeg',
  ['-hide_banner','-loglevel','error','-nostdin',...a],
  {stdio:['ignore','ignore','inherit']}
 );
}

function at(x){
 x=Math.max(0,+x||0);

 const h=Math.floor(x/3600);
 const m=Math.floor((x%3600)/60);
 const s=Math.floor(x%60);
 const c=Math.floor((x-Math.floor(x))*100);

 return `${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}.${String(c).padStart(2,'0')}`;
}

function ae(s){
 return String(s)
  .replace(/\\/g,'\\\\')
  .replace(/\{/g,'(')
  .replace(/\}/g,')')
  .replace(/\n/g,' ')
  .trim();
}

function normalizedParts(text){

 const m=String(text)
  .normalize('NFKC')
  .toLowerCase()
  .match(/[\p{L}\p{N}]+/gu);

 return m||[];
}

function sceneForRange(start,end){

 const mid=(Number(start)+Number(end))/2;

 for(let i=0;i<d.scenes.length;i++){

  const s=d.scenes[i];

  if(
   mid>=Number(s.start)-0.01 &&
   mid<=Number(s.end)+0.01
  ){
   return i;
  }
 }

 let best=0;
 let dist=Infinity;

 for(let i=0;i<d.scenes.length;i++){

  const s=d.scenes[i];
  const center=(Number(s.start)+Number(s.end))/2;
  const x=Math.abs(mid-center);

  if(x<dist){
   dist=x;
   best=i;
  }
 }

 return best;
}

function buildDisplayTokens(script,words){

 const raw=words
  .map(x=>({
   word:String(x.word||'').trim(),
   start:Number(x.start),
   end:Number(x.end)
  }))
  .filter(x=>
   x.word &&
   Number.isFinite(x.start) &&
   Number.isFinite(x.end)
  );

 const rawParts=[];

 raw.forEach((word,rawIndex)=>{

  for(const part of normalizedParts(word.word)){

   rawParts.push({
    text:part,
    rawIndex
   });
  }
 });

 const scriptTokens=String(script||'')
  .match(/\S+/g)||[];

 const result=[];

 let pos=0;

 for(const display of scriptTokens){

  const wanted=normalizedParts(display);

  if(!wanted.length){
   continue;
  }

  let found=-1;

  const searchEnd=Math.min(
   rawParts.length,
   pos+14
  );

  for(let start=pos;start<searchEnd;start++){

   if(start+wanted.length>rawParts.length){
    break;
   }

   let ok=true;

   for(let j=0;j<wanted.length;j++){

    if(rawParts[start+j].text!==wanted[j]){
     ok=false;
     break;
    }
   }

   if(ok){
    found=start;
    break;
   }
  }

  if(found===-1){
   continue;
  }

  const firstRaw=
   rawParts[found].rawIndex;

  const lastRaw=
   rawParts[found+wanted.length-1].rawIndex;

  const start=raw[firstRaw].start;
  const end=raw[lastRaw].end;

  result.push({
   word:display,
   start,
   end,
   scene:sceneForRange(start,end)
  });

  pos=found+wanted.length;
 }

 const coverage=
  raw.length ?
   result.length/raw.length :
   0;

 console.error(
  `Text alignment: ${result.length} display tokens from ${raw.length} Whisper words`
 );

 if(result.length<3){

  console.error(
   'Script alignment failed; falling back to Whisper text'
  );

  return raw.map(x=>({
   ...x,
   scene:sceneForRange(x.start,x.end)
  }));
 }

 return result;
}

function charWidth(ch){

 if(ch===' '){
  return .32;
 }

 if(/[ilI1.,'`:;!|]/.test(ch)){
  return .28;
 }

 if(/[mwMW@#%&]/.test(ch)){
  return .86;
 }

 if(/[A-Z]/.test(ch)){
  return .64;
 }

 if(/[0-9]/.test(ch)){
  return .57;
 }

 if(/[-–—]/.test(ch)){
  return .34;
 }

 return .53;
}

function textWidth(text,size=BASE_SIZE){

 let units=0;

 for(const ch of String(text)){
  units+=charWidth(ch);
 }

 return units*size;
}

function groupWidth(words){

 if(!words.length){
  return 0;
 }

 const base=
  words.reduce(
   (sum,x)=>sum+textWidth(x.word),
   0
  )+
  Math.max(0,words.length-1)*
  textWidth(' ');

 const activeExtra=
  Math.max(
   ...words.map(x=>
    textWidth(x.word)*
    ((ACTIVE_SCALE/100)-1)
   )
  );

 return base+activeExtra+20;
}

function makeKaraokeGroups(words){

 const groups=[];
 let current=[];

 function flush(){

  if(!current.length){
   return;
  }

  groups.push({
   start:current[0].start,
   end:current[current.length-1].end,
   scene:current[0].scene,
   words:current
  });

  current=[];
 }

 for(const word of words){

  if(current.length){

   const prev=
    current[current.length-1];

   const candidate=
    [...current,word];

   const sceneChanged=
    word.scene!==current[0].scene;

   const pause=
    word.start-prev.end;

   const tooLong=
    current.length>=MAX_GROUP_WORDS;

   const tooWide=
    groupWidth(candidate)>MAX_GROUP_WIDTH;

   if(
    sceneChanged ||
    pause>PAUSE_BREAK ||
    tooLong ||
    tooWide
   ){
    flush();
   }
  }

  current.push(word);

  if(/[.!?]["')\]]*$/.test(word.word)){
   flush();
  }
 }

 flush();

 return groups;
}

function karaokeText(group,activeIndex){

 return group.words.map((word,i)=>{

  const text=ae(word.word);

  if(i===activeIndex){

   return (
    `{\\c&H00D7FF&`+
    `\\b1`+
    `\\fscx${ACTIVE_SCALE}`+
    `\\fscy${ACTIVE_SCALE}`+
    `\\bord5}`+
    text+
    `{\\rKaraoke}`
   );
  }

  return text;

 }).join(' ');
}

if(!fs.existsSync(voice)){
 throw new Error('voiceover.mp3 missing');
}

if(!Array.isArray(d.scenes)||!d.scenes.length){
 throw new Error('No scenes');
}

if(!Array.isArray(d.words)||!d.words.length){
 throw new Error('No word timings');
}

if(!d.script){
 throw new Error('No script');
}

for(let i=0;i<d.scenes.length;i++){

 for(const f of [
  path.join(w,`image-${i+1}.jpg`),
  path.join(w,`scene-${i+1}.mp4`)
 ]){

  if(fs.existsSync(f)){
   fs.unlinkSync(f);
  }
 }
}

for(const f of [ass,list,joined,out]){

 if(fs.existsSync(f)){
  fs.unlinkSync(f);
 }
}

console.error(
 `Downloading ${d.scenes.length} images...`
);

for(let i=0;i<d.scenes.length;i++){

 console.error(
  `Image ${i+1}/${d.scenes.length}`
 );

 await dl(
  d.scenes[i].image_url,
  path.join(w,`image-${i+1}.jpg`)
 );
}

const displayTokens=
 buildDisplayTokens(
  d.script,
  d.words
 );

const karaokeGroups=
 makeKaraokeGroups(displayTokens);

console.error(
 `Karaoke groups: ${karaokeGroups.length}`
);

const head=`[Script Info]
ScriptType: v4.00+
PlayResX: 1080
PlayResY: 1920
ScaledBorderAndShadow: yes
WrapStyle: 0

[V4+ Styles]
Format: Name,Fontname,Fontsize,PrimaryColour,SecondaryColour,OutlineColour,BackColour,Bold,Italic,Underline,StrikeOut,ScaleX,ScaleY,Spacing,Angle,BorderStyle,Outline,Shadow,Alignment,MarginL,MarginR,MarginV,Encoding
Style: Karaoke,Arial,64,&H00FFFFFF,&H00FFFFFF,&H00000000,&H66000000,0,0,0,0,100,100,0,0,1,4,0,2,90,170,420,1

[Events]
Format: Layer,Start,End,Style,Name,MarginL,MarginR,MarginV,Effect,Text
`;

const events=[];

for(const group of karaokeGroups){

 let cursor=group.words[0].start;

 for(let i=0;i<group.words.length;i++){

  const word=group.words[i];

  const eventStart=
   Math.max(
    word.start,
    cursor
   );

  let eventEnd=
   Math.max(
    word.end,
    eventStart+0.04
   );

  if(i<group.words.length-1){

   const next=
    group.words[i+1];

   const gap=
    next.start-word.end;

   if(gap<=VISIBLE_GAP){

    eventEnd=
     Math.max(
      eventEnd,
      next.start
     );

   }else{

    eventEnd=
     Math.max(
      eventStart+0.04,
      word.end
     );
   }
  }

  if(eventEnd<=eventStart){
   eventEnd=eventStart+0.04;
  }

  events.push(
   `Dialogue: 0,${at(eventStart)},${at(eventEnd)},Karaoke,,0,0,0,,${karaokeText(group,i)}`
  );

  cursor=eventEnd;
 }
}

fs.writeFileSync(
 ass,
 head+
 events.join('\n')+
 '\n'
);

console.error(
 `Karaoke subtitles created: ${events.length} events`
);

for(let i=0;i<d.scenes.length;i++){

 const s=d.scenes[i];
 const img=path.join(w,`image-${i+1}.jpg`);
 const dst=path.join(w,`scene-${i+1}.mp4`);

 const dur=
  Math.max(
   .1,
   +s.duration||.1
  );

 const frames=
  Math.max(
   2,
   Math.round(dur*fps)
  );

 const last=
  Math.max(
   1,
   frames-1
  );

 let vf;

 if(s.motion==='pan_right'){

  vf=
   `scale=2160:3840:force_original_aspect_ratio=increase,`+
   `crop=2160:3840:`+
   `x='2*floor(((iw-2160)*n/${last})/2)':`+
   `y='2*floor(((ih-3840)/2)/2)',`+
   `scale=1080:1920:flags=lanczos,`+
   `setsar=1,fps=30,format=yuv420p`;

 }else if(s.motion==='pan_left'){

  vf=
   `scale=2160:3840:force_original_aspect_ratio=increase,`+
   `crop=2160:3840:`+
   `x='2*floor(((iw-2160)*(1-n/${last}))/2)':`+
   `y='2*floor(((ih-3840)/2)/2)',`+
   `scale=1080:1920:flags=lanczos,`+
   `setsar=1,fps=30,format=yuv420p`;

 }else if(s.motion==='zoom_out'){

  vf=
   `scale=2160:3840:force_original_aspect_ratio=increase,`+
   `crop=2160:3840,`+

   `scale=`+
   `w='max(2160,2*floor((2160*(1.12-0.12*n/${last}))/2))':`+
   `h='max(3840,2*floor((3840*(1.12-0.12*n/${last}))/2))':`+
   `eval=frame,`+

   `crop=2160:3840:`+
   `x='2*floor(((iw-2160)/2)/2)':`+
   `y='2*floor(((ih-3840)/2)/2)',`+

   `scale=1080:1920:flags=lanczos,`+
   `setsar=1,fps=30,format=yuv420p`;

 }else{

  vf=
   `scale=2160:3840:force_original_aspect_ratio=increase,`+
   `crop=2160:3840,`+

   `scale=`+
   `w='max(2160,2*floor((2160*(1+0.12*n/${last}))/2))':`+
   `h='max(3840,2*floor((3840*(1+0.12*n/${last}))/2))':`+
   `eval=frame,`+

   `crop=2160:3840:`+
   `x='2*floor(((iw-2160)/2)/2)':`+
   `y='2*floor(((ih-3840)/2)/2)',`+

   `scale=1080:1920:flags=lanczos,`+
   `setsar=1,fps=30,format=yuv420p`;
 }

 console.error(
  `Scene ${i+1}/${d.scenes.length}: ${s.motion} (${dur.toFixed(2)}s)`
 );

 ff([
  '-y',
  '-framerate','30',
  '-loop','1',
  '-i',img,
  '-vf',vf,
  '-frames:v',String(frames),
  '-an',
  '-c:v','libx264',
  '-preset','ultrafast',
  '-crf','20',
  '-threads','1',
  '-pix_fmt','yuv420p',
  '-r','30',
  dst
 ]);
}

fs.writeFileSync(
 list,
 d.scenes.map((_,i)=>
  `file '${path.join(w,`scene-${i+1}.mp4`)}'`
 ).join('\n')+
 '\n'
);

console.error('Joining scenes...');

ff([
 '-y',
 '-f','concat',
 '-safe','0',
 '-i',list,
 '-c','copy',
 joined
]);

console.error('Final render...');

ff([
 '-y',
 '-i',joined,
 '-i',voice,
 '-vf',`subtitles=${ass}`,
 '-map','0:v:0',
 '-map','1:a:0',
 '-c:v','libx264',
 '-preset','veryfast',
 '-crf','23',
 '-threads','1',
 '-pix_fmt','yuv420p',
 '-r','30',
 '-c:a','aac',
 '-b:a','128k',
 '-movflags','+faststart',
 '-shortest',
 out
]);

if(!fs.existsSync(out)||!fs.statSync(out).size){
 throw new Error('Final video missing');
}

const st=fs.statSync(out);

console.log(JSON.stringify({
 ok:true,
 video_path:out,
 video_size_mb:+(st.size/1048576).toFixed(2),
 scenes:d.scenes.length,
 display_tokens:displayTokens.length,
 karaoke_groups:karaokeGroups.length,
 karaoke_events:events.length,
 duration:d.duration
}));

console.error('Render complete');

})().catch(e=>{
 console.error(e.stack||e);
 process.exit(1);
});
NODE

